#include "overrides.h"
#include "override_data.h"   // generated by tools/embed_overrides.py: kEmbeddedOverrides (assets/overrides/)
#include "../game/map.h"     // userDataPath
#include <algorithm>
#include <cctype>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <map>
#include <mutex>

namespace fs = std::filesystem;

namespace {
bool g_useUser = true, g_scanned = false;
std::mutex g_mu;
std::string g_userRoot;
std::map<std::string, fs::path> g_user;   // lower-case relative path -> file

std::string lower(std::string s) { for (char& c : s) c = (char)std::tolower((unsigned char)c); std::replace(s.begin(), s.end(), '\\', '/'); return s; }

void scan() {
    std::lock_guard<std::mutex> l(g_mu);
    if (g_scanned) return;
    g_scanned = true;
    g_user.clear();
    {
        if (!g_useUser) return;
        g_userRoot = userDataPath("overrides");
        std::error_code ec;
        fs::path root = fs::u8path(g_userRoot);
        if (!fs::is_directory(root, ec)) return;   // the usual case: one stat, nothing else
        for (auto it = fs::recursive_directory_iterator(root, ec); !ec && it != fs::recursive_directory_iterator(); it.increment(ec))
            if (it->is_regular_file(ec)) g_user[lower(fs::relative(it->path(), root, ec).generic_u8string())] = it->path();
    }
}

bool readFile(const fs::path& p, std::vector<uint8_t>& out) {
    std::ifstream f(p, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end);
    std::streamoff n = f.tellg();
    if (n < 0 || n > (256 << 20)) return false;
    f.seekg(0);
    out.resize((size_t)n);
    return n == 0 || (bool)f.read((char*)out.data(), n);
}

const EmbeddedOverride* embedded(const std::string& key) {
    for (const EmbeddedOverride* e = kEmbeddedOverrides; e->path; e++)
        if (lower(e->path) == key) return e;
    return nullptr;
}
} // namespace

namespace overrides {
void useUserFolder(bool on) { std::lock_guard<std::mutex> l(g_mu); g_useUser = on; g_scanned = false; }

bool any() {
    scan();
    return kEmbeddedOverrides[0].path || !g_user.empty();
}

bool find(const std::string& base, std::initializer_list<const char*> exts, std::vector<uint8_t>& out, std::string* matched, std::string* where, From from) {
    if (!any()) return false;
    std::string b = lower(base);
    for (int pass = from == FROM_SHIPPED ? 1 : 0; pass < (from == FROM_USER ? 1 : 2); pass++)   // yours first, then the shipped ones
        for (const char* ext : exts) {
            std::string key = b + lower(ext);
            if (pass == 0) {
                auto it = g_user.find(key);
                if (it == g_user.end() || !readFile(it->second, out)) continue;
                if (where) *where = "user";
            } else {
                const EmbeddedOverride* e = embedded(key);
                if (!e) continue;
                out.assign(e->data, e->data + e->size);
                if (where) *where = "shipped";
            }
            if (matched) *matched = key;
            return true;
        }
    return false;
}

bool readRelative(const std::string& path, std::vector<uint8_t>& out, From from) {
    if (!any()) return false;
    std::string key = lower(path);
    if (from != FROM_SHIPPED) {
        auto it = g_user.find(key);
        if (it != g_user.end() && readFile(it->second, out)) return true;
    }
    if (from == FROM_USER) return false;
    if (const EmbeddedOverride* e = embedded(key)) { out.assign(e->data, e->data + e->size); return true; }
    return false;
}

std::string soundLevels() {
    if (!any()) return {};
    std::string text;
    if (const EmbeddedOverride* e = embedded("sound-levels.txt")) text.assign((const char*)e->data, e->size);
    auto it = g_user.find("sound-levels.txt");
    std::vector<uint8_t> b;
    if (it != g_user.end() && readFile(it->second, b)) { text += '\n'; text.append((const char*)b.data(), b.size()); }
    return text;
}

std::vector<std::string> listFolder(const std::string& dir, std::initializer_list<const char*> exts) {
    if (!any()) return {};
    std::string pre = lower(dir);
    while (!pre.empty() && pre.back() == '/') pre.pop_back();
    pre += '/';
    std::vector<std::string> out;
    auto take = [&](const std::string& key) {
        if (key.compare(0, pre.size(), pre) != 0) return;
        std::string rest = key.substr(pre.size());
        if (rest.find('/') != std::string::npos) return;
        for (const char* ext : exts) {
            std::string e = lower(ext);
            if (rest.size() > e.size() && rest.compare(rest.size() - e.size(), e.size(), e) == 0) { out.push_back(rest.substr(0, rest.size() - e.size())); return; }
        }
    };
    for (auto& kv : g_user) take(kv.first);
    for (const EmbeddedOverride* e = kEmbeddedOverrides; e->path; e++) take(lower(e->path));
    std::sort(out.begin(), out.end());
    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

std::vector<std::string> list() {
    scan();
    std::vector<std::string> v;
    for (const EmbeddedOverride* e = kEmbeddedOverrides; e->path; e++) v.push_back("shipped:" + lower(e->path));
    for (auto& kv : g_user) v.push_back("user:" + kv.first);
    return v;
}
} // namespace overrides
